import{_ as t,o as a,c as o,a1 as i}from"./chunks/framework.BKrM4vFX.js";const k=JSON.parse('{"title":"Интеграция: эквайринг Т-Банка через mock (10 минут)","description":"Интеграция: эквайринг Т-Банка через mock (10 минут). Мок воспроизводит контракт EACQ/Мультирасчеты по официальной документации (https://developer.tbank.ru/eacq): Init → платёжная форма → нотификации → Confirm/Cancel, плюс верификация счетов (AV) и e2c-выплаты. Мерчантская ","frontmatter":{"sourcePath":"docs/integration/tbank-eacq.md"},"headers":[{"level":1,"title":"Интеграция: эквайринг Т-Банка через mock (10 минут)","slug":"Интеграция-эквайринг-Т-Банка-через-mock-10-минут","link":"#Интеграция-эквайринг-Т-Банка-через-mock-10-минут","children":[{"level":2,"title":"1. Поднять стенд","slug":"_1-Поднять-стенд","link":"#_1-Поднять-стенд","children":[]},{"level":2,"title":"2. Базовый флоу","slug":"_2-Базовый-флоу","link":"#_2-Базовый-флоу","children":[]},{"level":2,"title":"3. Профили","slug":"_3-Профили","link":"#_3-Профили","children":[]},{"level":2,"title":"4. Что мок проверяет за вас (важно для отладки)","slug":"_4-Что-мок-проверяет-за-вас-важно-для-отладки","link":"#_4-Что-мок-проверяет-за-вас-важно-для-отладки","children":[]},{"level":2,"title":"5. Сценарии и консоль","slug":"_5-Сценарии-и-консоль","link":"#_5-Сценарии-и-консоль","children":[]},{"level":2,"title":"6. Ошибки (DX)","slug":"_6-Ошибки-dx","link":"#_6-Ошибки-dx","children":[]},{"level":2,"title":"7. Чеклист готовности к бою","slug":"_7-Чеклист-готовности-к-бою","link":"#_7-Чеклист-готовности-к-бою","children":[]},{"level":2,"title":"8. Ссылки","slug":"_8-Ссылки","link":"#_8-Ссылки","children":[]}]}],"relativePath":"docs/integration/tbank-eacq.md","filePath":"docs/integration/tbank-eacq.md"}'),c={name:"docs/integration/tbank-eacq.md"};function s(l,e,d,n,r,h){return a(),o("div",null,[...e[0]||(e[0]=[i(`<h1 id="Интеграция-эквайринг-Т-Банка-через-mock-10-минут" tabindex="-1">Интеграция: эквайринг Т-Банка через mock (10 минут) <a class="header-anchor" href="#Интеграция-эквайринг-Т-Банка-через-mock-10-минут" aria-label="Permalink to &quot;Интеграция: эквайринг Т-Банка через mock (10 минут)&quot;">​</a></h1><p>Мок воспроизводит контракт EACQ/Мультирасчеты по официальной документации (<a href="https://developer.tbank.ru/eacq" target="_blank" rel="noreferrer">https://developer.tbank.ru/eacq</a>): Init → платёжная форма → нотификации → Confirm/Cancel, плюс верификация счетов (AV) и e2c-выплаты.</p><h2 id="_1-Поднять-стенд" tabindex="-1">1. Поднять стенд <a class="header-anchor" href="#_1-Поднять-стенд" aria-label="Permalink to &quot;1. Поднять стенд&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">docker</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> compose</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> up</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> tbank-mock</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">     # http://localhost:3100</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># или без docker: npm run start:tbank</span></span></code></pre></div><p>Мерчантская часть (ваша интеграция) должна принимать вебхуки. Для локальной проверки укажите в Init <code>NotificationURL=http://host.docker.internal:PORT/webhook</code> или задайте <code>MOCK_DEFAULT_NOTIFICATION_URL</code> на стенде.</p><h2 id="_2-Базовый-флоу" tabindex="-1">2. Базовый флоу <a class="header-anchor" href="#_2-Базовый-флоу" aria-label="Permalink to &quot;2. Базовый флоу&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Init: создать платёжную сессию</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">curl</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -s</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> http://localhost:3100/v2/Init</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -H</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;Content-Type: application/json&#39;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -d</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;{</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">  &quot;TerminalKey&quot;: &quot;TBANKMOCKTEST&quot;, &quot;OrderId&quot;: &quot;order-1&quot;, &quot;Amount&quot;: 100000,</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">  &quot;CreateDealWithType&quot;: &quot;NN&quot;, &quot;NotificationURL&quot;: &quot;http://host.docker.internal:8080/webhook&quot;,</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">  &quot;SuccessURL&quot;: &quot;https://myapp.test/success/{order_id}&quot;, &quot;FailURL&quot;: &quot;https://myapp.test/fail/{order_id}&quot;</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">}&#39;</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># → { PaymentURL, PaymentId, Status: &quot;NEW&quot; }</span></span></code></pre></div><p>Откройте <code>PaymentURL</code> в браузере: на форме — тестовые карты со сценариями (успех/3DS-challenge/недостаточно средств/отказ). Коды 3DS: <code>1qwezxc</code>.</p><ol start="3"><li>Подпись. Каждый API-запрос подписывается <code>Token</code> = sha256 по алгоритму «значения top-level скаляров (без Token, null, пустых) + Password, отсортированные по ключу, boolean в нижнем регистре» — конспект с примерами: <code>документации Т-Банка</code>. Нотификации от мока подписаны так же; мерчант обязан проверять (мок умеет слать дубли — кнопка в <code>/admin</code>, для проверки идемпотентности).</li></ol><h2 id="_3-Профили" tabindex="-1">3. Профили <a class="header-anchor" href="#_3-Профили" aria-label="Permalink to &quot;3. Профили&quot;">​</a></h2><p><code>MOCK_PROFILE=plain</code> (по умолчанию) — классический эквайринг без сделок: мультирасчётные поля (DealId/CreateDealWithType/PaymentRecipientId) игнорируются как незнакомые банку. <code>MOCK_PROFILE=multisplit</code> — профиль со сделками (Мультирасчеты): платёж с <code>PaymentRecipientId</code> требует <code>DealId</code> или <code>CreateDealWithType=NN</code>.</p><h2 id="_4-Что-мок-проверяет-за-вас-важно-для-отладки" tabindex="-1">4. Что мок проверяет за вас (важно для отладки) <a class="header-anchor" href="#_4-Что-мок-проверяет-за-вас-важно-для-отладки" aria-label="Permalink to &quot;4. Что мок проверяет за вас (важно для отладки)&quot;">​</a></h2><p>Мок ведёт себя как банк там, где ошибка интегратора была бы незаметна локально:</p><table tabindex="0"><thead><tr><th>Проверка</th><th>Ответ мока</th></tr></thead><tbody><tr><td><code>Token</code> короткий/битый (не 64 hex)</td><td><code>ErrorCode 13</code>, а не «внутренняя ошибка»</td></tr><tr><td>Чужой <code>TerminalKey</code></td><td><code>ErrorCode 7</code> с названием ожидаемого терминала</td></tr><tr><td>Повторный <code>Init</code> с тем же <code>OrderId</code></td><td><code>ErrorCode 7</code> (в бою <code>OrderId</code> уникален); отключается <code>MOCK_ALLOW_DUPLICATE_ORDER_ID=true</code></td></tr><tr><td><code>Cancel</code> с <code>Amount</code> больше доступной суммы</td><td><code>ErrorCode 7</code> + <code>OriginalAmount</code> (раньше выполнялся полный возврат!)</td></tr><tr><td><code>Confirm</code> не из <code>AUTHORIZED</code></td><td><code>ErrorCode 32</code> (операция недоступна в статусе)</td></tr><tr><td><code>GetState</code> без <code>PaymentId</code></td><td>принимается <code>OrderId</code>; при нескольких платежах — <code>ErrorCode 7</code> со списком <code>PaymentId</code></td></tr></tbody></table><p>Журнал запросов: <code>GET /admin/journal</code> (JSON) и таблица в <code>/admin</code> — видно метод, путь, ключевые поля, код ответа и время обработки: «что мок понял в моём запросе».</p><h2 id="_5-Сценарии-и-консоль" tabindex="-1">5. Сценарии и консоль <a class="header-anchor" href="#_5-Сценарии-и-консоль" aria-label="Permalink to &quot;5. Сценарии и консоль&quot;">​</a></h2><p><code>/admin</code> — платежи со историей статусов, сделки (баланс), поступления AV, верификации, нотификации (статус доставки, ретраи, кнопка «повторить»), кнопки сценариев: «банк подтвердил холд», «отмена платформой», «чарджбэк эмитента».</p><h2 id="_6-Ошибки-dx" tabindex="-1">6. Ошибки (DX) <a class="header-anchor" href="#_6-Ошибки-dx" aria-label="Permalink to &quot;6. Ошибки (DX)&quot;">​</a></h2><p>Ошибка — не голый код: <code>Details</code> содержит <code>Field</code> (какое поле), <code>Hint</code> (рекомендация) и <code>Doc</code> (раздел официальной документации). Известные коды: 7 (невалидные параметры), 8 (не найдено), 13 (подпись), 32 (недоступно в статусе), 501 (метод не реализован в моке).</p><h2 id="_7-Чеклист-готовности-к-бою" tabindex="-1">7. Чеклист готовности к бою <a class="header-anchor" href="#_7-Чеклист-готовности-к-бою" aria-label="Permalink to &quot;7. Чеклист готовности к бою&quot;">​</a></h2><ul><li>[ ] все нотификации проверяют Token, ответ 200 «OK» ровно на подтверждённые</li><li>[ ] дубли и ретраи нотификаций обрабатываются идемпотентно (кнопка «повторить»/«дубль»)</li><li>[ ] переходы Confirm/Cancel только из допустимых статусов (см. историю в /admin)</li><li>[ ] чарджбэк-сценарий доводит вашу логику до корректного финала</li><li>[ ] повторный <code>Init</code> с тем же <code>OrderId</code> (ретрай сети) не создаёт второй платёж</li><li>[ ] <code>Cancel</code> не превышает доступную сумму и повторяется идемпотентно (<code>ExternalRequestId</code>)</li><li>[ ] рестарт стенда с <code>MOCK_STATE_FILE</code> не теряет необработанные нотификации (недоставленные догоняются после подъёма)</li><li>[ ] смена <code>TBANK_API_URL</code> на боевой хост + реальные TerminalKey/Password — код интеграции не меняется</li></ul><h2 id="_8-Ссылки" tabindex="-1">8. Ссылки <a class="header-anchor" href="#_8-Ссылки" aria-label="Permalink to &quot;8. Ссылки&quot;">​</a></h2><ul><li>Контракт сервиса, env, профили и <code>/mock/*</code>: <a href="./../../services/tbank-mock/README"><code>services/tbank-mock/README.md</code></a></li><li>OpenAPI 3.1: <a href="https://github.com/rucorp/mock-services/blob/main/docs/openapi/tbank-mock.openapi.json" target="_blank" rel="noreferrer"><code>docs/openapi/tbank-mock.openapi.json</code></a></li><li>Манифест протокола для <code>npm run check:drift</code>: <a href="https://github.com/rucorp/mock-services/blob/main/protocols/tbank-eacq.json" target="_blank" rel="noreferrer"><code>protocols/tbank-eacq.json</code></a></li><li>Общая инфраструктура адаптеров (часы, песочницы, вебхуки, SSRF): <a href="./../../packages/core/README"><code>packages/core/README.md</code></a></li></ul>`,24)])])}const _=t(c,[["render",s]]);export{k as __pageData,_ as default};
